std::vector<int> V = {1, 2, 2, 3, 2, 4};
// Count occurrences of 2
long n_count = std::count(V.begin(), V.end(), 2); // 3

// Check if all elements are even
bool all_even = std::all_of(V.begin(), V.end(),
                            [](int x){ return x % 2 == 0; }); // false

std::vector<int> V2 = {10, 20, 30};
std::list<int> L2 = {10, 20, 30};
// Compare ranges
bool are_equal = std::equal(V2.begin(), V2.end(), L2.begin()); // true

// Find the first element >= 3 (using find_if)
auto it = std::find_if(V.begin(), V.end(),
                       [](int x){ return x >= 3; });
// *it == 3
